// One-off generator for test/fixtures/card-vectors.json (card 85818ab1, REFINE "Copy rule"). Run once; its output is
// committed and never regenerated by the tests. It runs the OBSERVATORY's own card and receipt code (src/card.ts,
// src/contract.ts @76f2837) on fixed inputs, signs one receipt the way its recorder does (a throwaway Ed25519 key,
// the private half never written), and records each answer. test/cards-vectors.test.ts requires the vault's copies
// (vault/src/cardcopy.ts) to give the same answers and to accept that receipt.
//
// Usage: node test/fixtures/make-card-vectors.ts <dir holding observatory src/ at 76f2837> > test/fixtures/card-vectors.json
// (e.g. git -C <observatory clone> archive 76f2837 src | tar -x -C <dir>)
import { pathToFileURL } from "node:url";

const dir = process.argv[2];
if (!dir) throw new Error("usage: make-card-vectors.ts <observatory dir>");
const card = await import(pathToFileURL(`${dir}/src/card.ts`).href);
const contract = await import(pathToFileURL(`${dir}/src/contract.ts`).href);
const records = await import(pathToFileURL(`${dir}/src/records.ts`).href);

const h = (c: string) => c.repeat(64);
const good = { kind: "card/v1", card: "card-0001-abcd", requester: "c-box agent", entries: [h("a"), h("b")], deadline: 1_800_001_500_000, jobs_version: 1 };
const manifests: [string, unknown][] = [
  ["valid", good],
  ["one entry", { ...good, entries: [h("c")] }],
  ["extra field", { ...good, extra: 1 }],
  ["missing field", (({ jobs_version: _, ...m }) => m)(good)],
  ["wrong kind", { ...good, kind: "card/v2" }],
  ["bad card id", { ...good, card: "x" }],
  ["empty requester", { ...good, requester: "" }],
  ["no entries", { ...good, entries: [] }],
  ["six entries", { ...good, entries: ["1", "2", "3", "4", "5", "6"].map(h) }],
  ["duplicate entries", { ...good, entries: [h("a"), h("a")] }],
  ["uppercase hash", { ...good, entries: ["A".repeat(64)] }],
  ["zero deadline", { ...good, deadline: 0 }],
  ["fraction version", { ...good, jobs_version: 1.5 }],
  ["negative zero deadline", { ...good, deadline: -0 }],
  ["array", [good]],
];
const out: Record<string, unknown> = { source: "observatory @76f2837", recorder_key: records.PIN.key, card_eligible: card.CARD_ELIGIBLE, card_run_ms: card.CARD_RUN_MS, card_max: card.CARD_MAX, manifests: [] as unknown[] };
for (const [name, m] of manifests) {
  const parsed = card.parseManifest(m);
  // -0 does not survive JSON; it is rebuilt by name in the test.
  (out.manifests as unknown[]).push({ name, manifest: m, verdict: typeof parsed === "string" ? parsed : null, card_hash: typeof parsed === "string" ? null : await card.cardHashOf(parsed) });
}
const chal = (bytes: number[]) => Buffer.from(JSON.stringify({ type: "webauthn.get", challenge: Buffer.from(bytes).toString("base64url") })).toString("base64url");
out.challenges = [
  { name: "48 bytes", client_data_json: chal([...Array(16).fill(1), ...Array(32).fill(0xab)]) },
  { name: "32 bytes", client_data_json: chal(Array(32).fill(0xab)) },
  { name: "not json", client_data_json: "!!!" },
].map((c) => ({ ...c, hash: card.challengeHash({ client_data_json: c.client_data_json }) ?? null }));
const pair = (await crypto.subtle.generateKey("Ed25519", true, ["sign", "verify"])) as CryptoKeyPair;
const receipt = { v: 1, seq: 42, key: "records/v1/000000000042.card-0001-abcd.approval.json", grant: "card-0001-abcd", stage: "approval", sha256: h("d"), recorded_at: "2027-01-15T08:00:00.000Z" };
out.receipt = {
  receipt: { ...receipt, sig: contract.b64(await crypto.subtle.sign("Ed25519", pair.privateKey, contract.receiptSealed(receipt))) },
  key: contract.b64(await crypto.subtle.exportKey("raw", pair.publicKey)),
  sealed: contract.b64(contract.receiptSealed(receipt)),
};
console.log(JSON.stringify(out, null, 1));
